import itertools, numpy as np
outs=[np.array([[v==8 for v in row] for row in o]) for g,o in demos]
# For d1/d4 compare primary-color density in blocks under all partitions of rows/cols into 3 groups (ordered nonempty contiguous)
gs=[]
for a in range(1,7):
 for b in range(a+1,7): gs.append([list(range(0,a)),list(range(a,b)),list(range(b,7))])
for typ in ('main','nonzero','zero'):
 hits=[]
 for R in gs:
  for C in gs:
   mats=[]
   for ix in (0,3):
    g=demos[ix][0]
    main=max(set(sum(g,[]))-{0}, key=lambda c:sum(v==c for row in g for v in row))
    mats.append(np.array([[sum((g[r][c]==main if typ=='main' else g[r][c]!=0 if typ=='nonzero' else g[r][c]==0) for r in rr for c in cc) / len(rr)/len(cc) for cc in C] for rr in R]))
   if np.all((mats[0]>=0.5)==outs[0]) and np.all((mats[1]>=0.5)==outs[3]): hits.append((R,C,mats))
 print(typ,len(hits))
